import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/DIS.DdpTdGGD.js";import{_ as t,o as r,c as n,a3 as o}from"./chunks/framework.g9mfNVRQ.js";const g=JSON.parse('{"title":"Li3","description":"","frontmatter":{"source_hash":"a98504fa65","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/install/li3.md","filePath":"fr/install/li3.md"}'),s={name:"fr/install/li3.md"};function l(p,i,c,d,u,m){return r(),n("div",null,[...i[0]||(i[0]=[o('<div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Paramètres<br>  Source de données matérielle<br>   Li3</p></div><p>La source de données Li3, ajoutée dans la version <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer">2026.11.21</a>, connecte xDrip directement à un appareil Li3. Vous pouvez aussi la sélectionner avec l&#39;<a href="./datasource.html">assistant de source</a>, dans le groupe Libre.</p><p>xDrip démarre une nouvelle session, ou reprend une session en cours, par un scan NFC. Il reçoit ensuite les valeurs par Bluetooth.</p><ul><li>Les valeurs arrivent toutes les 5 minutes, ou toutes les minutes si <a href="./../use/misc.html">Libre 1 minute</a> est activé.</li><li>Lorsque la connexion revient après une interruption, xDrip complète les valeurs manquantes à partir de l&#39;historique de l&#39;appareil. Les valeurs déjà enregistrées ne sont jamais remplacées.</li><li><strong>Cette source de données ne peut pas être étalonnée.</strong> Si vous essayez, xDrip affiche <em>This sensor cannot be calibrated.</em> (ce capteur ne peut pas être calibré).</li></ul><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>Lorsque xDrip démarre ou reprend une session, l&#39;application officielle ne reçoit plus ses valeurs ni ses alarmes.</p></div><br><h2 id="before-you-start" tabindex="-1">Avant de commencer <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Avant de commencer {#before-you-start}&quot;">​</a></h2><ul><li>Votre téléphone doit disposer du NFC. Sans NFC, xDrip affiche <em>This phone has no NFC, so it cannot start a Li3.</em> (ce téléphone n&#39;a pas de NFC, il ne peut donc pas démarrer un Li3).</li><li>Activez le NFC dans les paramètres du téléphone. xDrip propose d&#39;activer son propre scan NFC s&#39;il est désactivé.</li><li>xDrip a besoin de l&#39;autorisation de localisation, et la localisation doit être activée, pour rechercher l&#39;appareil en Bluetooth. L&#39;écran Li3 demande ce qui manque.</li><li>Une connexion Internet est nécessaire une fois, pour télécharger l&#39;identifiant d&#39;application (app credential).</li><li>Si ce n&#39;est pas encore fait, <a href="./install.html#make-sure-xdrip-will-not-be-put-to-sleep">vérifiez que xDrip ne sera pas mis en veille</a>.</li></ul><br><h2 id="the-li3-screen" tabindex="-1">L&#39;écran Li3 <a class="header-anchor" href="#the-li3-screen" aria-label="Permalink to &quot;L&#39;écran Li3 {#the-li3-screen}&quot;">​</a></h2><p>L&#39;écran Li3 liste les étapes de configuration, indique où vous en êtes et lit les scans NFC tant qu&#39;il est ouvert.<br> Il s&#39;ouvre de lui-même lorsque vous sélectionnez la source de données Li3, et lorsque vous appuyez sur Démarrer le capteur alors qu&#39;aucun capteur n&#39;est démarré. Vous pouvez aussi l&#39;ouvrir depuis État du système :</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> État du système<br>  Li3 Status<br>   Li3  Open</p></div><p>Tant que la configuration n&#39;est pas terminée, xDrip affiche aussi une notification qui ouvre cet écran : <em>Li3 setup not finished; open System Status, Li3</em>.</p><p>Si vous scannez l&#39;appareil alors qu&#39;un autre écran est ouvert, xDrip ouvre l&#39;écran Li3 et vous demande de scanner à nouveau depuis celui-ci : <em>Scan the device again on the Li3 screen to start it or take it over</em>.</p><br><h2 id="setup" tabindex="-1">Configuration <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Configuration {#setup}&quot;">​</a></h2><h4 id="1-download-the-app-credential" tabindex="-1">1. Télécharger l&#39;identifiant d&#39;application <a class="header-anchor" href="#1-download-the-app-credential" aria-label="Permalink to &quot;1. Télécharger l&#39;identifiant d&#39;application {#1-download-the-app-credential}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  DOWNLOAD APP CREDENTIAL </div></p></div><p>L&#39;appareil s&#39;appaire à l&#39;aide d&#39;un identifiant d&#39;application. S&#39;il n&#39;a pas encore été téléchargé, xDrip propose de le télécharger à l&#39;ouverture de l&#39;écran Li3.<br> Une fois le téléchargement terminé, la ligne App credential sous les boutons indique <em>Downloaded</em>. Si le téléchargement échoue, vérifiez votre connexion Internet et appuyez de nouveau sur Download.</p><h4 id="2-account-id-only-to-take-over-a-session-started-by-an-official-app" tabindex="-1">2. ID de compte (uniquement pour reprendre une session démarrée par une application officielle) <a class="header-anchor" href="#2-account-id-only-to-take-over-a-session-started-by-an-official-app" aria-label="Permalink to &quot;2. ID de compte (uniquement pour reprendre une session démarrée par une application officielle) {#2-account-id-only-to-take-over-a-session-started-by-an-official-app}&quot;">​</a></h4><p>Passez cette étape pour démarrer une nouvelle session pour xDrip.</p><p>Pour reprendre une session démarrée par une application officielle, xDrip a besoin de l&#39;ID de compte (Account ID) de cette application.</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  LOOK UP ACCOUNT ID </div></p></div><p>Connectez-vous avec le compte qui a démarré la session, et non avec un compte abonné. xDrip ne conserve que l&#39;ID de compte, ni l&#39;e-mail ni le mot de passe.<br> Si la connexion est refusée en raison de nouvelles conditions d&#39;utilisation, ouvrez l&#39;application officielle avec ce compte, acceptez les conditions, puis réessayez.<br> Si la recherche échoue, vous pouvez saisir vous-même l&#39;ID de compte dans les <a href="#li3-settings">paramètres Li3</a>.</p><p>Choisissez ensuite l&#39;application qui a démarré la session :</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  SENSOR APP: LI3 APP </div></p></div><div class="admonition xdripitem"><p class="admonition-title">Which app started this session?</p><p> Li3 app<br>  Multi-sensor app</p></div><h4 id="3-scan-the-device" tabindex="-1">3. Scanner l&#39;appareil <a class="header-anchor" href="#3-scan-the-device" aria-label="Permalink to &quot;3. Scanner l&#39;appareil {#3-scan-the-device}&quot;">​</a></h4><p>L&#39;écran Li3 ouvert, scannez l&#39;appareil avec votre téléphone. xDrip pose l&#39;une de ces questions :</p><table tabindex="0"><thead><tr><th>Appareil</th><th>ID de compte défini</th><th>Pas d&#39;ID de compte</th></tr></thead><tbody><tr><td>Neuf</td><td><strong>Start Sensor</strong> : xDrip reçoit les valeurs. L&#39;application officielle pourra reprendre l&#39;appareil plus tard avec le même compte.</td><td><strong>Start Sensor</strong> : la session est réservée à xDrip sur ce téléphone. <strong>L&#39;appareil ne pourra jamais passer à une application officielle, et il est perdu si xDrip est réinstallé.</strong></td></tr><tr><td>Session en cours</td><td><strong>Take over Li3</strong> : l&#39;application officielle ne reçoit plus ses valeurs ni ses alarmes.</td><td>Ne fonctionne que pour une session démarrée par xDrip sur ce téléphone. Pour une session démarrée par une application officielle, recherchez d&#39;abord son ID de compte.</td></tr></tbody></table><p>Sans ID de compte, vous pouvez appuyer sur <em>Look up account ID</em>, ou sur <em>Scan anyway</em> pour continuer sans.</p><p>Appuyez sur OK, puis <strong>scannez à nouveau l&#39;appareil dans les cinq minutes</strong> pour confirmer.<br> Lorsque cela fonctionne, xDrip affiche <em>Li3 ready, connecting by Bluetooth</em>.</p><p>Si l&#39;appareil refuse la commande, vérifiez que l&#39;application et l&#39;ID de compte sont bien ceux avec lesquels la session a été démarrée.<br> Si xDrip utilise déjà cet appareil, rien n&#39;est envoyé. Pour l&#39;appairer à nouveau, appuyez sur Oublier ce périphérique dans l&#39;écran Li3, puis scannez-le.</p><h4 id="4-wait-for-the-first-reading" tabindex="-1">4. Attendre la première valeur <a class="header-anchor" href="#4-wait-for-the-first-reading" aria-label="Permalink to &quot;4. Attendre la première valeur {#4-wait-for-the-first-reading}&quot;">​</a></h4><p>Un appareil neuf n&#39;envoie aucune valeur pendant sa première heure environ.</p><br><h2 id="li3-settings" tabindex="-1">Paramètres Li3 <a class="header-anchor" href="#li3-settings" aria-label="Permalink to &quot;Paramètres Li3 {#li3-settings}&quot;">​</a></h2><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Paramètres<br>   Paramètres moins courants<br>    Autres options diverses<br>     Li3</p></div><div class="admonition xdripitem"><p class="admonition-title">Account ID</p><p> Needed to take over a session in progress. Leave empty to start a new session for xDrip on this phone only.</p></div><p>Look up account ID, dans l&#39;écran Li3, le remplit pour vous.</p><div class="admonition xdripitem"><p class="admonition-title">Official app</p><p> The app the account uses</p></div><p>Li3 app (par défaut) ou Multi-sensor app. C&#39;est le même choix que le bouton Sensor app de l&#39;écran Li3.</p><div class="admonition xdripitem"><p class="admonition-title">Smooth Li3 readings <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Average recent readings to make them smoother</p></div><p>Les paramètres NFC qui ne s&#39;appliquent pas au Li3 (âge du capteur, jours avant expiration, multibloc, toute balise, streaming Bluetooth Libre 2) sont masqués tant que Li3 est la source de données.</p><br><h2 id="status" tabindex="-1">État <a class="header-anchor" href="#status" aria-label="Permalink to &quot;État {#status}&quot;">​</a></h2><p>L&#39;écran Li3 et État du système → Li3 Status affichent :</p><ul><li><strong>Device</strong> (appareil)</li><li><strong>Stage</strong> (étape) : ce que fait xDrip en ce moment, par exemple : <ul><li><em>No device; scan one with NFC</em></li><li><em>No app credential; tap Download on the Li3 screen</em></li><li><em>Looking for the device; keep the phone near it</em></li><li><em>Lost the device; trying again soon</em></li><li><em>Connected; waiting for a reading</em></li><li><em>Session ended; scan a new device with NFC</em></li></ul></li><li><strong>Last error</strong> (dernière erreur)</li><li><strong>Reading not stored</strong> (valeur non enregistrée), lorsque xDrip a refusé une valeur : pas de valeur valide, heure de début de session apparemment erronée, ou valeur marquée comme non fiable par l&#39;appareil</li><li><strong>Started</strong> (démarré) et <strong>Sensor life</strong> (durée de vie du capteur) (ou <em>Expired</em>)</li><li><strong>Last reading</strong> (dernière valeur)</li><li><strong>App credential</strong> (identifiant d&#39;application)</li></ul><h4 id="forget-device" tabindex="-1">Oublier ce périphérique <a class="header-anchor" href="#forget-device" aria-label="Permalink to &quot;Oublier ce périphérique {#forget-device}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  OUBLIER CE PÉRIPHÉRIQUE </div></p></div><p>xDrip cesse de communiquer avec cet appareil. Pour l&#39;utiliser à nouveau, scannez-le en NFC.<br> Une session démarrée sans compte ne peut revenir qu&#39;à xDrip sur ce téléphone.</p><h4 id="copy-diagnostics" tabindex="-1">Copier les diagnostics <a class="header-anchor" href="#copy-diagnostics" aria-label="Permalink to &quot;Copier les diagnostics {#copy-diagnostics}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  COPY DIAGNOSTICS </div></p></div><p>Copie les informations de diagnostic dans le presse-papiers. Collez-les lorsque vous demandez de l&#39;aide.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 22/11/2026</em></a></p>',56)])])}const b=t(s,[["render",l]]);export{g as __pageData,b as default};
